                (
                    StatusCode::NOT_FOUND,
                    Json(ErrorBody {
                        error: format!("版本 {version} 不存在或尚未保存"),
                        index: None,
                    }),
                )
            })
    };
    let from_snapshot = find(params.from)?;
    let to_snapshot = find(params.to)?;
    drop(store);

    // 两份快照的记录都按键字典序排列，归并迭代即得键并集的有序变化列表。
